import{Q as e,X as t,ft as n,n as r}from"./chunks/framework.DnzEF-oq.js";var i=JSON.parse(`{"title":"A Vision for Recon","description":"","frontmatter":{"title":"A Vision for Recon","updated":"2026-10-15T00:00:00.000Z"},"headers":[],"relativePath":"VISION.md","filePath":"VISION.md"}`),a={name:`VISION.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="a-vision-for-recon" tabindex="-1">A Vision for Recon <a class="header-anchor" href="#a-vision-for-recon" aria-label="Permalink to “A Vision for Recon”">​</a></h1><h2 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to “Introduction”">​</a></h2><p>Recon is an agent-facing workbench for understanding how applications behave when their implementation is unavailable. It is for researchers and developers who need to turn observations of reference applications, starting with those that run on macOS, into reproducible behavioral specifications. A useful answer must say what was tried, what happened, and which evidence supports the claim, so another person or agent can challenge it.</p><h2 id="current-capabilities" tabindex="-1">Current capabilities <a class="header-anchor" href="#current-capabilities" aria-label="Permalink to “Current capabilities”">​</a></h2><p>Recon can list discovered and running macOS application bundles, inspect one bundle&#39;s metadata and running process IDs without activating it, and explicitly launch the selected bundle through its Rust CLI. It can also observe a running macOS application without activating it, changing focus, or sending input: list its windows, read the accessibility tree of the application or of one window, including windows on other Spaces, and capture one window to a PNG file. Those observations use Screen Recording and Accessibility permissions that belong to the locally signed <code>recon</code> executable rather than to the program that launched it. UI interaction, native analysis, Electron and web application investigation, experiments, behavioral specifications, verification, and persistent evidence remain future work toward the minimum viable product. Windows and Android investigation come after it.</p><h2 id="goals" tabindex="-1">Goals <a class="header-anchor" href="#goals" aria-label="Permalink to “Goals”">​</a></h2><ul><li>Make feature discovery systematic: find candidate behaviors, distinguish observations from hypotheses, and keep unanswered questions visible.</li><li>Make controlled experiments repeatable enough to isolate the effect of an input, environment change, or action sequence on the reference application&#39;s behavior.</li><li>Turn observed behavior into precise specifications that can be tested against an independent implementation.</li><li>Make differential verification explain agreements and disagreements with the reference, including the evidence behind each conclusion.</li><li>Preserve observations, artifacts, conditions, and provenance across agent sessions so findings can be revisited rather than rediscovered.</li></ul><h2 id="minimum-viable-product" tabindex="-1">Minimum viable product <a class="header-anchor" href="#minimum-viable-product" aria-label="Permalink to “Minimum viable product”">​</a></h2><p>The first useful Recon completes a bounded investigation of reference applications running on macOS through its Rust CLI: native macOS applications, Electron applications, and web applications in a browser. An agent can enumerate an application, discover multiple feature entry points and contextual prerequisites, resume its session with evidence intact, run a parameterized JSONC experiment, and turn the observations into a behavioral specification. It can execute equivalent behavior against a reference and an independent implementation, reporting matches, meaningful discrepancies, and inconclusive comparisons. SQLite stores structured records and content-addressed storage keeps larger artifacts; every claim remains traceable to observations, conditions, application versions, and the experiment that supports it.</p><p>Native analysis through REA and supported UI adapters must report unavailable capabilities and permission failures explicitly. The minimum proves the investigation loop on purpose-built macOS fixtures for native, Electron, and web applications; it does not imply that every feature of a complex proprietary application can already be explored automatically. Windows, Android, and other platforms are beyond the minimum.</p><h2 id="design-principles" tabindex="-1">Design principles <a class="header-anchor" href="#design-principles" aria-label="Permalink to “Design principles”">​</a></h2><ul><li><strong>Evidence before confidence.</strong> Keep raw observations, conditions, and interpretations distinguishable; a behavioral claim must point back to the experiment that supports it.</li><li><strong>Control before coverage.</strong> Prefer a small experiment with a clear baseline and variation over broad but ambiguous capture. When they conflict, reproducibility takes precedence over the number of explored features.</li><li><strong>Agents can inspect the whole trail.</strong> Favor a Rust CLI and structured, durable experiment and result records that an agent can read, write, and revisit without relying on transient chat history. Human readers need the same trail to be legible.</li><li><strong>Analysis and orchestration have separate owners.</strong> REA is the primary reverse-engineering analysis backend; Recon owns the investigation workflow, behavioral records, and comparison of evidence. An integration must preserve that boundary rather than duplicate REA&#39;s analysis.</li><li><strong>Uncertainty stays explicit.</strong> A mismatch is a finding to investigate, not proof that either the reference or independent implementation is wrong. Report missing evidence and environmental differences rather than manufacture agreement.</li></ul><h2 id="beyond-the-minimum" tabindex="-1">Beyond the minimum <a class="header-anchor" href="#beyond-the-minimum" aria-label="Permalink to “Beyond the minimum”">​</a></h2><ul><li>Investigation on Windows, Android, and other platforms. The minimum needs one host platform to prove the investigation loop, and each further platform needs its own grounding of what an installed application and a running instance are.</li><li>Broader discovery across complex third-party applications and reusable experiments spanning multiple application families, once the macOS fixture loop is reliable.</li><li>Integrations with tools such as re-cli or winctl/winctl-win where they provide real analysis or application control capabilities; the boundaries and suitability of each require separate evaluation.</li><li>Authenticated remote hosts and optional MCP integration, after local CLI investigations can be reproduced reliably.</li></ul><h2 id="non-goals" tabindex="-1">Non-goals <a class="header-anchor" href="#non-goals" aria-label="Permalink to “Non-goals”">​</a></h2><ul><li>An autonomous coding agent or application generator. Recon supplies evidence and tools to an external agent rather than choosing and implementing a recreation on its behalf.</li><li>Source-code recovery or a faithful clone of an application. The target is externally observable behavior; implementation details are only relevant when they help explain or verify it.</li><li>Exhaustive, unattended exploration of every application. The initial value comes from a traceable investigation of a bounded behavior, where an agent or researcher can choose and revise the question.</li><li>Treating one observation or a passing comparison as a universal specification. Platform, version, state, and experimental conditions limit what the evidence establishes.</li><li>Replacing REA as a reverse-engineering analysis backend. A second analysis engine would blur responsibility before the evidence workflow is proven.</li></ul><h2 id="revision-history" tabindex="-1">Revision history <a class="header-anchor" href="#revision-history" aria-label="Permalink to “Revision history”">​</a></h2><table tabindex="0"><thead><tr><th>Date</th><th>Change</th><th>Related proposal</th></tr></thead><tbody><tr><td>2026-10-14</td><td>Created the initial project vision.</td><td>N/A</td></tr><tr><td>2026-10-15</td><td>Added macOS application investigation through the Rust CLI.</td><td>proposal.0001</td></tr><tr><td>2026-10-15</td><td>Limited the minimum viable product to macOS, including Electron and web applications; moved Windows and Android beyond it.</td><td>N/A</td></tr><tr><td>2026-10-15</td><td>Added macOS UI observation of windows, accessibility trees, and window screenshots.</td><td>proposal.0002</td></tr></tbody></table>`,18)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};